def register_server(
    name: str,
    host: str,
    user: str,
    port: int = 22,
    gpu_count: int = 0,
    vram_gb: int = 0,
    available: bool = True,
    work_dir: str = "~",
    env_activate: str = "",
    password: [REDACTED] = "",
) -> ToolResult:
    """Register a new GPU server in config/resources.yaml.

    Connects directly to the target host via SSH (bypasses resources.yaml).
    If gpu_count is 0 or omitted, auto-probes GPUs via nvidia-smi.

    Args:
        name: Server name (must be a safe identifier, e.g. "RTX4090", "A100_2").
        host: Hostname or IP, e.g. "10.0.0.1".
        user: SSH username.
        gpu_count: Number of GPUs. 0 = auto-detect via nvidia-smi.
        vram_gb: VRAM per GPU in GB. 0 = auto-detect.
        available: Whether GPUs are initially available (default True).
        work_dir: Default working directory for this account.
        env_activate: Environment activation command.
        port: SSH port (default 22). Used for AutoDL instances with non-standard ports.
        password: [REDACTED] password (encrypted and stored). Used for AutoDL instances.

    Returns:
        ToolResult with the new server config including detected GPU info.
    """
    name = _validate_identifier(name, label="server name")

    if not host or not user:
        return ToolResult(
            success=False,
            error=f"Both host and user are required. Got host={host!r}, user={user!r}.",
        )

    resources = _load_resources()
    servers = resources.setdefault("servers", {})

    if name in servers:
        return ToolResult(
            success=False,
            error=f"Server '{name}' already exists. Remove it first or use a different name.",
        )

    # Auto-probe GPUs if not specified
    gpu_name = ""
    if gpu_count <= 0 or vram_gb <= 0:
        try:
            probed_count, probed_vram, gpu_name = _probe_gpus(host, user, port=port, password=[REDACTED]
            if gpu_count <= 0:
                gpu_count = probed_count
            if vram_gb <= 0:
                vram_gb = probed_vram
        except Exception as e:
            return ToolResult(
                success=False,
                error=f"Failed to auto-detect GPUs on {user}@{host}: {e}. "
                      f"Provide gpu_count and vram_gb manually.",
            )

    if gpu_count < 1 or gpu_count > 16:
        return ToolResult(
            success=False,
            error=f"gpu_count must be 1-16, got {gpu_count}.",
        )

    gpus = [
        {"id": f"cuda:{i}", "vram_gb": vram_gb, "available": available}
        for i in range(gpu_count)
    ]

    # Probe hardware (RAM, CPU, cgroup limits, disk) — best-effort
    hw = _probe_hardware(host, user, port=port, password=[REDACTED]
    hardware_info: dict[str, Any] = {
